package main
import("bytes";"encoding/json";"log";"net/http";"os";"runtime";"strconv";"strings";"syscall";"time")
type registrationPayload struct{Name string `json:"name"`;Location string `json:"location"`;BaseURL string `json:"baseUrl"`;CapacityCPU float64 `json:"capacityCpu"`;CapacityMemoryMB int64 `json:"capacityMemoryMb"`;CapacityDiskMB int64 `json:"capacityDiskMb"`;AgentVersion string `json:"agentVersion"`}
func init(){go registrationLoop()}
func nodeCapacity()(int64,int64){var m syscall.Sysinfo_t;if syscall.Sysinfo(&m)!=nil{return 256,1024};unit:=uint64(m.Unit);if unit==0{unit=1};mem:=int64(uint64(m.Totalram)*unit/1024/1024);var fs syscall.Statfs_t;disk:=int64(1024);if syscall.Statfs("/",&fs)==nil{disk=int64(fs.Blocks)*int64(fs.Bsize)/1024/1024};return mem,disk}
func registrationLoop(){panel:=strings.TrimRight(env("CRAKNODE_PANEL_URL",""),"/");token:=env("CRAKNODE_REGISTRATION_TOKEN","");if panel==""||token==""{log.Println("auto registration disabled: CRAKNODE_PANEL_URL or CRAKNODE_REGISTRATION_TOKEN missing");return};interval:=60*time.Second;if n,e:=strconv.Atoi(env("CRAKNODE_HEARTBEAT_INTERVAL","60"));e==nil&&n>=15&&n<=3600{interval=time.Duration(n)*time.Second};send:=func(){mem,disk:=nodeCapacity();host,_:=os.Hostname();name:=env("CRAKNODE_NAME",host);if name==""{name="craknode"};p:=registrationPayload{Name:name,Location:env("CRAKNODE_LOCATION","Auto Registered"),BaseURL:env("CRAKNODE_PUBLIC_URL","http://craknode:8088"),CapacityCPU:float64(runtime.NumCPU()),CapacityMemoryMB:mem,CapacityDiskMB:disk,AgentVersion:version};raw,_:=json.Marshal(p);req,e:=http.NewRequest(http.MethodPost,panel+"/api/nodes/register",bytes.NewReader(raw));if e!=nil{return};req.Header.Set("content-type","application/json");req.Header.Set("x-craknode-registration-token",token);r,e:=(&http.Client{Timeout:8*time.Second}).Do(req);if e!=nil{log.Printf("node registration failed: %v",e);return};defer r.Body.Close();if r.StatusCode<200||r.StatusCode>=300{log.Printf("node registration rejected: HTTP %d",r.StatusCode);return};log.Printf("node registered/heartbeat sent: %s",name)};send();t:=time.NewTicker(interval);defer t.Stop();for range t.C{send()}}
